pm.test('Script-tag payload is rejected or sanitised', () => {
  pm.expect([201, 400]).to.include(pm.response.code);
});

pm.test('No raw script tags leak through', () => {
  if (pm.response.code === 201) {
    const raw = JSON.stringify(pm.response.json());
    pm.expect(raw).to.not.match(/<script>/i);
    pm.expect(raw).to.not.match(/onerror\s*=/i);
  } else {
    // 400 means the request was refused — that's also secure
    pm.expect(pm.response.json().success).to.eql(false);
  }
});

